import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import CarForm from './components/CarForm';
import RentalForm from './components/RentalForm';
import Receipt from './components/Receipt';
import CustomerPage from './components/CustomerPage';
import PaymentPage from './components/PaymentPage';
import BranchPage from './components/BranchPage';
import LoginPage from './components/LoginPage';
import api from './api';

const statusStyles = {

    'Available': {
        bg: '#d1fae5',
        text: '#065f46'
    },

    'Rented': {
        bg: '#dbeafe',
        text: '#1e40af'
    },

    'Under Maintenance': {
        bg: '#fef3c7',
        text: '#92400e'
    }

};

function App() {

    const navigate = useNavigate();
    const location = useLocation();
    const tab = location.pathname === '/' ? 'cars' : location.pathname.slice(1);

    const [loggedIn, setLoggedIn] = useState(false);
    const [adminUser, setAdminUser] = useState(null);
    const [checkingAuth, setCheckingAuth] = useState(true);

    const [items, setItems] = useState([]);
    const [editingItem, setEditingItem] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [search, setSearch] = useState('');
    const [showForm, setShowForm] = useState(false);
    const [rentingCar, setRentingCar] = useState(null);
    const [receipt, setReceipt] = useState(null);

    const [rentals, setRentals] = useState([]);
    const [loadingRentals, setLoadingRentals] = useState(false);

    useEffect(function() {

        var token = localStorage.getItem('authToken');
        var savedUser = localStorage.getItem('adminUser');

        if (token && savedUser) {

            api.validateToken().then(function() {
                setAdminUser(JSON.parse(savedUser));
                setLoggedIn(true);
                setCheckingAuth(false);
            }).catch(function() {
                localStorage.removeItem('authToken');
                localStorage.removeItem('adminUser');
                setCheckingAuth(false);
            });

        } else {
            setCheckingAuth(false);
        }

    }, []);

    function handleLogin(data) {

        localStorage.setItem('authToken', data.token);
        localStorage.setItem('adminUser', JSON.stringify(data));
        setAdminUser(data);
        setLoggedIn(true);

    }

    function handleLogout() {

        api.logout().catch(function() {});
        localStorage.removeItem('authToken');
        localStorage.removeItem('adminUser');
        setLoggedIn(false);
        setAdminUser(null);

    }

    var fetchItems = useCallback(async function() {

        try {

            setLoading(true);
            var response = await api.findAllCars();
            setItems(response.data);
            setError('');

        } catch (err) {

            setError('Failed to fetch cars. Is the server running?');

        } finally {

            setLoading(false);

        }

    }, []);

    function fetchRentals() {

        setLoadingRentals(true);

        api.findAllRentals().then(function(response) {
            setRentals(response.data);
            setLoadingRentals(false);
        }).catch(function() {
            setLoadingRentals(false);
        });

    }

    useEffect(function() {

        if (loggedIn) {
            fetchItems();
        }

    }, [loggedIn, fetchItems]);

    useEffect(function() {

        if (loggedIn && tab === 'rentals') {
            fetchRentals();
        }

    }, [loggedIn, tab]);

    async function handleAddOrUpdate(data) {

        try {

            if (editingItem) {

                await api.updateCar(editingItem.id, data);

            } else {

                await api.saveCar(data);

            }

            setEditingItem(null);
            setShowForm(false);
            await fetchItems();

        } catch (err) {

            var message = err.response?.data?.message || 'Failed to save car.';
            setError(message);

        }

    }

    function handleEdit(item) {

        setEditingItem(item);
        setShowForm(true);
        window.scrollTo({ top: 0, behavior: 'smooth' });

    }

    async function handleDelete(id) {

        var confirmed = window.confirm('Remove this car from rental inventory?');

        if (!confirmed) {
            return;
        }

        try {

            await api.deleteCar(id);
            await fetchItems();

        } catch (err) {

            var message = err.response?.data?.message || 'Failed to delete car.';
            setError(message);

        }

    }

    async function handleRent(rentalData) {

        try {

            var res = await api.rentCar(rentalData);
            setReceipt(res.data);
            setRentingCar(null);
            await fetchItems();

        } catch (err) {

            var message = err.response?.data?.message || 'Failed to process rental.';
            setError(message);

        }

    }

    function closeReceipt() {
        setReceipt(null);
    }

    if (checkingAuth) {

        return (

            <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#fafafa' }}>
                <p style={{ color: '#6b7280' }}>Loading...</p>
            </div>

        );

    }

    if (!loggedIn) {

        return <LoginPage onLogin={handleLogin} />;

    }

    var filtered = items.filter(function(car) {

        var nameMatch = car.carName && car.carName.toLowerCase().includes(search.toLowerCase());
        var brandMatch = car.brand && car.brand.toLowerCase().includes(search.toLowerCase());
        var plateMatch = car.plateNumber && car.plateNumber.toLowerCase().includes(search.toLowerCase());

        return nameMatch || brandMatch || plateMatch;

    });

    var available = items.filter(function(car) {
        return car.status === 'Available';
    }).length;

    var rented = items.filter(function(car) {
        return car.status === 'Rented';
    }).length;

    var tabStyle = function(isActive) {

        return {
            padding: '0.6rem 1.2rem',
            background: isActive ? '#fbbf24' : 'transparent',
            color: isActive ? '#1a1a2e' : '#9ca3af',
            border: 'none',
            borderRadius: '8px',
            cursor: 'pointer',
            fontWeight: isActive ? 700 : 500,
            fontSize: '0.85rem',
            transition: 'all 0.15s'
        };

    };

    var tabContent;

    if (tab === 'cars') {

        tabContent = (

            <div>

                {receipt && <Receipt data={receipt} onClose={closeReceipt} />}

                {rentingCar && !receipt && (

                    <div style={{ maxWidth: '550px', margin: '0 auto 2rem' }}>

                        <RentalForm car={rentingCar} onSubmit={handleRent} onCancel={function() { setRentingCar(null); }} />

                    </div>

                )}

                {!showForm && !rentingCar && !receipt && (

                    <>

                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))', gap: '0.8rem', marginBottom: '1.5rem' }}>

                            <div style={{ background: '#fff', borderRadius: '10px', padding: '1rem', boxShadow: '0 1px 3px rgba(0,0,0,0.04)', textAlign: 'center', border: '1px solid #e5e7eb' }}>

                                <div style={{ color: '#6b7280', fontSize: '0.7rem', textTransform: 'uppercase', letterSpacing: '0.5px', fontWeight: 500 }}>
                                    Total Cars
                                </div>

                                <div style={{ fontSize: '1.6rem', fontWeight: 700, color: '#1a1a2e' }}>
                                    {items.length}
                                </div>

                            </div>

                            <div style={{ background: '#fff', borderRadius: '10px', padding: '1rem', boxShadow: '0 1px 3px rgba(0,0,0,0.04)', textAlign: 'center', border: '1px solid #d1fae5' }}>

                                <div style={{ color: '#065f46', fontSize: '0.7rem', textTransform: 'uppercase', letterSpacing: '0.5px', fontWeight: 500 }}>
                                    Available for Rent
                                </div>

                                <div style={{ fontSize: '1.6rem', fontWeight: 700, color: '#059669' }}>
                                    {available}
                                </div>

                            </div>

                            <div style={{ background: '#fff', borderRadius: '10px', padding: '1rem', boxShadow: '0 1px 3px rgba(0,0,0,0.04)', textAlign: 'center', border: '1px solid #dbeafe' }}>

                                <div style={{ color: '#1e40af', fontSize: '0.7rem', textTransform: 'uppercase', letterSpacing: '0.5px', fontWeight: 500 }}>
                                    Currently Rented
                                </div>

                                <div style={{ fontSize: '1.6rem', fontWeight: 700, color: '#2563eb' }}>
                                    {rented}
                                </div>

                            </div>

                        </div>

                        <div style={{ marginBottom: '1.2rem', display: 'flex', gap: '0.75rem' }}>

                            <input type="text"
                                placeholder="Search by car name, brand, or plate..."
                                value={search}
                                onChange={function(e) { setSearch(e.target.value); }}
                                style={{ flex: 1, padding: '0.65rem 1rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', outline: 'none', background: '#fff' }} />

                        </div>

                    </>

                )}

                {showForm && !rentingCar && (

                    <div style={{ maxWidth: '580px', margin: '0 auto 2rem' }}>

                        <CarForm
                            onSubmit={handleAddOrUpdate}
                            editingItem={editingItem}
                            onCancelEdit={function() {
                                setEditingItem(null);
                                setShowForm(false);
                            }} />

                    </div>

                )}

                {!showForm && !rentingCar && !receipt && (

                    loading ? (

                        <div style={{ textAlign: 'center', padding: '3rem' }}>

                            <p style={{ color: '#6b7280' }}>
                                Loading cars...
                            </p>

                        </div>

                    ) : (

                        <div style={{ display: 'grid', gap: '0.75rem' }}>

                            {filtered.length === 0 ? (

                                <div style={{ textAlign: 'center', padding: '3rem', background: '#fff', borderRadius: '10px', border: '1px solid #e5e7eb' }}>

                                    <p style={{ color: '#6b7280' }}>
                                        {search ? 'No cars match your search' : 'No cars in rental inventory yet'}
                                    </p>

                                </div>

                            ) : filtered.map(function(car) {

                                var ss = statusStyles[car.status] || statusStyles['Available'];

                                return (

                                    <div key={car.id}
                                        style={{ background: '#fff', borderRadius: '12px', overflow: 'hidden', boxShadow: '0 1px 4px rgba(0,0,0,0.06)', border: '1px solid #e5e7eb' }}>

                                        <div style={{ display: 'flex', alignItems: 'center', padding: '1rem 1.2rem', gap: '1rem' }}>

                                            <div style={{ flex: 1, minWidth: 0 }}>

                                                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', flexWrap: 'wrap' }}>

                                                    <h3 style={{ margin: 0, fontSize: '1.05rem', color: '#111827', fontWeight: 600 }}>
                                                        {car.carName}
                                                    </h3>

                                                    <span style={{ background: '#f3f4f6', color: '#4b5563', padding: '0.1rem 0.5rem', borderRadius: '4px', fontSize: '0.75rem', fontFamily: 'monospace' }}>
                                                        {car.plateNumber}
                                                    </span>

                                                    <span style={{ background: ss.bg, color: ss.text, padding: '0.15rem 0.6rem', borderRadius: '12px', fontSize: '0.75rem', fontWeight: 500 }}>
                                                        {car.status}
                                                    </span>

                                                </div>

                                                <div style={{ color: '#6b7280', fontSize: '0.85rem', marginTop: '0.2rem', display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>

                                                    <span>{car.brand} {car.model} ({car.manufactureYear})</span>

                                                    <span style={{ color: '#059669', fontWeight: 600 }}>
                                                        TSh {car.rentalPricePerDay?.toLocaleString()}<span style={{ color: '#9ca3af', fontWeight: 400 }}>/day</span>
                                                    </span>

                                                </div>

                                                {car.branchId && (
                                                    <div style={{ fontSize: '0.8rem', color: '#9ca3af', marginTop: '0.15rem' }}>
                                                        Branch ID: {car.branchId}
                                                    </div>
                                                )}

                                            </div>

                                            <div style={{ display: 'flex', gap: '0.4rem', flexShrink: 0 }}>

                                                {car.status === 'Available' && (

                                                    <button onClick={function() { setRentingCar(car); }}
                                                        style={{ background: '#059669', color: '#fff', border: 'none', padding: '0.35rem 0.8rem', borderRadius: '6px', cursor: 'pointer', fontSize: '0.8rem', fontWeight: 600 }}>
                                                        Rent
                                                    </button>

                                                )}

                                                <button onClick={function() { handleEdit(car); }}
                                                    style={{ background: '#fffbeb', color: '#92400e', border: '1px solid #fde68a', padding: '0.35rem 0.7rem', borderRadius: '6px', cursor: 'pointer', fontSize: '0.8rem' }}>
                                                    Edit
                                                </button>

                                                <button onClick={function() { handleDelete(car.id); }}
                                                    style={{ background: '#fef2f2', color: '#dc2626', border: '1px solid #fecaca', padding: '0.35rem 0.7rem', borderRadius: '6px', cursor: 'pointer', fontSize: '0.8rem' }}>
                                                    Delete
                                                </button>

                                            </div>

                                        </div>

                                    </div>

                                );

                            })}

                        </div>

                    )

                )}

            </div>

        );

    } else if (tab === 'rentals') {

        tabContent = (

            <div>

                <h2 style={{ color: '#1a1a2e', marginBottom: '0.8rem', fontSize: '1.1rem' }}>Rental Records</h2>

                {loadingRentals ? (

                    <p style={{ color: '#6b7280' }}>Loading rentals...</p>

                ) : rentals.length === 0 ? (

                    <div style={{ textAlign: 'center', padding: '1.5rem', background: '#fff', borderRadius: '10px', border: '1px solid #e5e7eb' }}>

                        <p style={{ color: '#6b7280' }}>No rental records yet.</p>

                    </div>

                ) : rentals.map(function(rental) {

                    return (

                        <div key={rental.id}
                            style={{ background: '#fff', borderRadius: '8px', padding: '0.7rem 1rem', marginBottom: '0.5rem', border: '1px solid #e5e7eb' }}>

                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>

                                <div>

                                    <div style={{ fontWeight: 600, color: '#111827', fontSize: '0.9rem' }}>
                                        {rental.carName} ({rental.plateNumber})
                                    </div>

                                    <div style={{ fontSize: '0.78rem', color: '#6b7280', marginTop: '0.15rem' }}>
                                        Customer: {rental.customerName} | Phone: {rental.customerPhone}
                                    </div>

                                    <div style={{ fontSize: '0.78rem', color: '#6b7280' }}>
                                        {rental.pickupDate} to {rental.returnDate} | {rental.rentalDays} day(s)
                                    </div>

                                    <div style={{ fontSize: '0.82rem', fontWeight: 600, color: '#059669', marginTop: '0.15rem' }}>
                                        Total: TSh {rental.totalCost?.toLocaleString()}
                                    </div>

                                </div>

                            </div>

                        </div>

                    );

                })}

            </div>

        );

    } else if (tab === 'customers') {

        tabContent = <CustomerPage />;

    } else if (tab === 'payments') {

        tabContent = <PaymentPage />;

    } else if (tab === 'branches') {

        tabContent = <BranchPage />;

    }

    return (

        <div style={{ minHeight: '100vh', background: '#fafafa' }}>

            <header style={{ background: 'linear-gradient(135deg, #1a1a2e 0%, #141428 100%)', padding: '1.2rem 2rem', color: '#fff', borderBottom: '3px solid #fbbf24' }}>

                <div style={{ maxWidth: '1100px', margin: '0 auto', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>

                    <div>

                        <h1 style={{ margin: 0, fontSize: '1.3rem', fontWeight: 700, letterSpacing: '0.5px' }}>
                            CAR<span style={{ color: '#fbbf24' }}>RENTAL</span>
                        </h1>

                        <p style={{ margin: '0.1rem 0 0', opacity: 0.5, fontSize: '0.8rem' }}>
                            Vehicle Rental Services
                        </p>

                    </div>

                    <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>

                        {tab === 'cars' && !showForm && !rentingCar && (

                            <button onClick={function() {
                                setShowForm(true);
                                setEditingItem(null);
                            }}
                                style={{ background: '#fbbf24', color: '#1a1a2e', border: 'none', padding: '0.5rem 1.2rem', borderRadius: '8px', cursor: 'pointer', fontWeight: 700, fontSize: '0.9rem' }}>
                                Add Rental Car
                            </button>

                        )}

                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>

                            <span style={{ fontSize: '0.8rem', color: '#9ca3af' }}>
                                {adminUser?.fullName || adminUser?.username}
                            </span>

                            <button onClick={handleLogout}
                                style={{ background: 'rgba(255,255,255,0.1)', color: '#f87171', border: '1px solid rgba(248,113,113,0.3)', padding: '0.4rem 0.9rem', borderRadius: '6px', cursor: 'pointer', fontSize: '0.8rem', fontWeight: 600 }}>
                                Logout
                            </button>

                        </div>

                    </div>

                </div>

            </header>

            <div style={{ background: '#fff', borderBottom: '1px solid #e5e7eb', padding: '0.6rem 2rem' }}>

                <div style={{ maxWidth: '1100px', margin: '0 auto', display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>

                    <button onClick={function() { navigate('/cars'); }}
                        style={tabStyle(tab === 'cars')}>
                        Cars
                    </button>

                    <button onClick={function() { navigate('/rentals'); }}
                        style={tabStyle(tab === 'rentals')}>
                        Rentals
                    </button>

                    <button onClick={function() { navigate('/customers'); }}
                        style={tabStyle(tab === 'customers')}>
                        Customers
                    </button>

                    <button onClick={function() { navigate('/payments'); }}
                        style={tabStyle(tab === 'payments')}>
                        Payments
                    </button>

                    <button onClick={function() { navigate('/branches'); }}
                        style={tabStyle(tab === 'branches')}>
                        Branches
                    </button>

                </div>

            </div>

            <div style={{ maxWidth: '1100px', margin: '0 auto', padding: '1.5rem 2rem' }}>

                {error && (

                    <div style={{ background: '#fef2f2', color: '#dc2626', padding: '0.75rem 1rem', borderRadius: '8px', marginBottom: '1.2rem', display: 'flex', justifyContent: 'space-between' }}>

                        <span>Error: {error}</span>

                        <button onClick={function() { setError(''); }}
                            style={{ background: 'none', border: 'none', color: '#dc2626', cursor: 'pointer', fontWeight: 'bold' }}>
                            X
                        </button>

                    </div>

                )}

                {tabContent}

            </div>

        </div>

    );

}

export default App;
